style:
margin: 0;
padding: 0;
border: none;
display: flex;
flex-direction: column;
gap: 8px;

.f-radio {
  position: relative;
  display: flex;
  align-items: center;

  input {
    position: absolute !important;
    opacity: 0 !important;
    width: 1px !important;
    height: 1px !important;
    pointer-events: none !important;

    &:checked + label {
      color: #00ae9a;
    }

    &:checked + label::before {
      border-color: #00ae9a;
    }

    &:checked + label::after {
      opacity: 1;
    }
  }

  label {
    display: inline-flex;
    align-items: center;
    position: relative;
    cursor: pointer;
    opacity: 1;
    line-height: 1.2;
    padding: 0 0 0 26px;
    user-select: none;
    transition: color 0.2s ease-in-out;

    &:hover {
      color: #00ae9a;
    }

    &:hover::before {
      border-color: #00ae9a;
    }

    &::before,
    &::after {
      display: block;
      content: '';
      position: absolute;
      border-radius: 50%;
      transition: all 0.2s ease-in-out;
    }

    &::before {
      left: 0;
      top: 50%;
      transform: translateY(-50%);
      width: 16px;
      height: 16px;
      border: 2px solid #94a3b8;
      background: transparent;
      box-sizing: border-box;
    }

    &::after {
      left: 4px;
      top: 50%;
      transform: translateY(-50%);
      width: 8px;
      height: 8px;
      background-color: #00ae9a;
      opacity: 0;
      box-sizing: border-box;
    }
  }
}
